def gcd(a, b):
    if a == b:
        return a
    elif a > b:
        return gcd(a - b, b)
    else:
        return gcd(a, b - a)


def gcdv2(a, b):
    if b == 0:
        return a
    else:
        return gcd(b, a % b)


