def pow(a, n):
    if n == 0:
        return 1
    return pow(a, n - 1) * a

def pow2(a, n):
    if n == 0:
        return 1
    if n % 2 != 0:
        return pow(a, n - 1) * a
    else:
        return pow(a ** 2, n / 2)

